import networkx as nx
G = nx.Graph()
for i in range(21):
    G.add_node(i)
for i in range(21):
    for j in range(i+1, 21):
        if (i+j) % 2 == 0:
            G.add_edge(i, j)
if nx.girth(G) >= 8 and nx.is_colorable(G, 4) and G.number_of_edges() >= 40:
    print("SATISFIABLE")
    print(list(G.edges))
else:
    print("UNSATISFIABLE")
